const pick = k => { if (typeof H[k] === 'number') return H[k]; if (typeof O[k] === 'number') { usaO.add(k); return O[k]; } return undefined; };
// a média nunca inclui o próprio dia comparado (hoje, ou ontem nas somas diárias)
const baseDe = k => ehOntem(k) ? dias.filter(d => d < ontem).slice(-30) : ultimos;
const media = k => { const v = baseDe(k).map(d => S.dias[d][k]).filter(x => typeof x === 'number'); return v.length >= 5 ? Math.round(v.reduce((a, b) => a + b, 0) / v.length * 10) / 10 : null; };
// (chave, nome, unidade, de onde vem o valor de hoje, sentido ruim: -1 cair, +1 subir)
const METS = [
  ['sono_total', 'Sono total', 'min', H.sono_total, -1], ['sono_cama', 'Tempo na cama (sem dados de sono dormido)', 'min', H.sono_cama, -1], ['sono_profundo', 'Sono profundo', 'min', H.sono_profundo, -1], ['sono_rem', 'Sono REM', 'min', H.sono_rem, -1],
