};
const rel = [], ok = [], resumoNum = [], dirs = [], faltam = [], outras = [];
let sinais = 0;
const fmt = x => String(Math.round(x * 10) / 10).replace('.', ',');
for (const [k, nome, un, hoje, s] of METS) {
  if (typeof hoje !== 'number') { if (k !== 'sono_cama' && k !== 'sono_profundo' && k !== 'sono_rem') faltam.push(nome.replace(' de ontem', '')); continue; }
  const med = media(k);
  if (med === null) { resumoNum.push(nome + ': ' + fmt(hoje) + (un ? ' ' + un : '') + ' (ainda sem média para comparar: poucos dias de histórico)'); continue; }
  const [nivel, pct] = classificar(k, hoje, med, s);
  const txt = nome + ': ' + (ehOntem(k) ? '' : 'hoje ') + fmt(hoje) + (un ? ' ' + un : '') + ', média de 30 dias ' + fmt(med) + ' (' + (pct >= 0 ? '+' : '') + Math.round(pct) + '%)';
