  if (nivel === 'normal') ok.push(txt);
  else { rel.push(txt + ' [' + (nivel === 'forte' ? 'MUITO RELEVANTE' : 'relevante') + ']'); dirs.push({ k, nome, subiu: hoje > med }); }
