}
// demais métricas recebidas: compara com o padrão da própria pessoa (sem critério clínico); métrica sem dado é ignorada
const PT = { heart_rate: 'Frequência cardíaca média', walking_heart_rate_average: 'Frequência cardíaca ao caminhar', body_temperature: 'Temperatura corporal', apple_sleeping_wrist_temperature: 'Temperatura do pulso no sono', weight_body_mass: 'Peso', vo2_max: 'VO2 máximo', walking_speed: 'Velocidade de caminhada', cardio_recovery: 'Recuperação cardíaca', time_in_daylight: 'Tempo à luz do dia', apple_exercise_time: 'Minutos de exercício', apple_stand_hour: 'Horas em pé', flights_climbed: 'Andares subidos', walking_running_distance: 'Distância a pé', basal_energy_burned: 'Energia em repouso', breathing_disturbances: 'Distúrbios respiratórios no sono', headphone_audio_exposure: 'Volume nos fones', environmental_audio_exposure: 'Ruído do ambiente', pressao_sistolica: 'Pressão sistólica', pressao_diastolica: 'Pressão diastólica', walking_double_support_percentage: 'Apoio duplo ao caminhar', walking_asymmetry_percentage: 'Assimetria ao caminhar', atrial_fibrillation_burden: 'Carga de fibrilação atrial', physical_effort: 'Esforço físico', mindful_minutes: 'Minutos de atenção plena', walking_step_length: 'Comprimento do passo', stair_speed_up: 'Velocidade ao subir escadas', stair_speed_down: 'Velocidade ao descer escadas', apple_stand_time: 'Tempo em pé', walking_running_distance: 'Distância a pé' };
const chavesGen = new Set();
for (const d of dias.concat([ymd, ontem])) for (const k of Object.keys(S.dias[d] || {})) if (k.indexOf('x:') === 0) chavesGen.add(k);
const gen = []; let genAnalisadas = 0;
for (const k of chavesGen) {
  const soma0 = (S.modo || {})[k] === 'soma';
  const hoje = soma0 ? O[k] : pick(k);
  const soma = soma0 || usaO.has(k);
  if (typeof hoje !== 'number') continue;
  const v = baseDe(k).map(d => S.dias[d][k]).filter(x => typeof x === 'number');
  if (v.length < 5) continue;
  genAnalisadas++;
  const med = v.reduce((a, b) => a + b, 0) / v.length;
  const dp = Math.sqrt(v.reduce((a, b) => a + (b - med) * (b - med), 0) / v.length);
  const pct = med ? 100 * (hoje - med) / Math.abs(med) : 0;
  const z = dp > 0 ? Math.abs(hoje - med) / dp : (hoje !== med ? 99 : 0);
  const nm = k.slice(2);
  const un = ((S.un || {})[k] || '').replace(/^count\/min$/, 'bpm').replace(/^count$/, '');
  const nome = PT[nm] || (nm.charAt(0).toUpperCase() + nm.slice(1).replace(/_/g, ' '));
  const febre = nm === 'body_temperature' && hoje >= 37.8;
  if (febre || (z >= 2.5 && Math.abs(pct) >= 15)) gen.push({ k, nome, un, hoje, med, pct, z: febre ? 100 : z, febre });
  else outras.push(nome + ': ' + (soma ? 'ontem ' : 'hoje ') + fmt(hoje) + (un ? ' ' + un : '') + ', média ' + fmt(med) + ' (' + (pct >= 0 ? '+' : '') + Math.round(pct) + '%)');
}
gen.sort((a, b) => b.z - a.z);
for (const g of gen.slice(0, 5)) {
  const txt = g.nome + ': ' + (ehOntem(g.k) ? 'ontem ' : 'hoje ') + fmt(g.hoje) + (g.un ? ' ' + g.un : '') + ', média de 30 dias ' + fmt(g.med) + ' (' + (g.pct >= 0 ? '+' : '') + Math.round(g.pct) + '%)';
  rel.push(txt + (g.febre ? ' [MUITO RELEVANTE]' : ' [fora do seu padrão]')); resumoNum.push(txt); dirs.push({ k: g.k, nome: g.nome, subiu: g.hoje > g.med });
}
const extra = genAnalisadas ? 'Outras métricas analisadas hoje: ' + genAnalisadas + ', com ' + gen.length + ' fora do seu padrão.' : '';
// dados que só o Apple Watch gera: se sumiram há dias, o motivo mais provável é o relógio não ter sido usado ou sincronizado
const DO_RELOGIO = ['fc_repouso', 'hrv', 'resp', 'spo2', 'sono_total', 'sono_cama'];
const ultimoRel = dias.concat([ymd]).filter(d => DO_RELOGIO.some(k => typeof (S.dias[d] || {})[k] === 'number')).pop() || '';
const diasSemRel = ultimoRel ? Math.round((new Date(ymd + 'T12:00:00Z') - new Date(ultimoRel + 'T12:00:00Z')) / 86400000) : 99;
const semRelogio = diasSemRel >= 2;
const comBase = resumoNum.filter(x => x.indexOf('sem média') < 0).length;
const recebidoH = S.recebido ? (Date.now() - S.recebido) / 3600000 : null;
let aviso = '';
if (!S.recebido) aviso = 'Ainda não recebi nenhum dado do iPhone.';
else if (recebidoH > 20) aviso = 'O iPhone não enviou dados novos há ' + Math.round(recebidoH) + ' horas; o resumo usa o que já tinha.';
if (semRelogio) aviso += (aviso ? ' ' : '') + (ultimoRel ? 'Faz ' + diasSemRel + ' dias (desde ' + ultimoRel + ') que não chegam dados do Apple Watch: sono, pulso, variabilidade, respiração e oxigênio. O relógio provavelmente não foi usado ou não sincronizou.' : 'Nunca recebi dados do Apple Watch (sono, pulso, variabilidade, respiração e oxigênio).');
else if (typeof H.sono_total !== 'number') aviso += (aviso ? ' ' : '') + 'Não recebi o sono desta noite.';
const padrao = sinais >= 3 ? sinais + ' dos 4 sinais de recuperação (sono total, variabilidade, pulso em repouso, respiração no sono) pioraram juntos.' : rel.length ? 'Há sinais isolados, sem um padrão claro de recuperação ruim.' : 'Nada saiu do esperado.';
const semModelo = comBase === 0 && !outras.length;
const nHist = dias.length;
const prompt = 'Você escreve o resumo diário de saúde de um adulto, em português do Brasil. O texto será lido por um leitor de tela: só parágrafos curtos, sem listas, sem negrito, sem tabelas, sem símbolos.\n\n'
  + 'REGRAS: as classificações abaixo já foram decididas e você não as discute. Fale só do que está em RELEVANTE e dê o sentido certo de cada variação (subiu ou caiu, como está escrito). Do que está em DENTRO DO NORMAL, diga numa frase que está normal. Não trate variação pequena como alerta. Itens "de ontem" são do dia anterior inteiro; os "de hoje" são do que já foi medido até agora. Se RELEVANTE estiver vazio, diga em uma frase que nada saiu do esperado e use o resto para manter hábitos, sem inventar problema. Se faltarem dados ou o histórico for curto, diga isso numa frase, sem dramatizar. Quando um item for "de ontem", escreva "ontem", nunca "hoje". Não atribua causas de comportamento como motivação ou preguiça, nem cite clima ou agenda. '
