    const frases = texto.split(/(?<=[.!?])\s+/);
    for (const f of frases) {
      const tocados = Object.keys(KEY).filter(k => KEY[k].test(f));
      if (tocados.length !== 1) continue;
      const d = P.dirs.find(x => x.k === tocados[0]);
      if (!d) continue;
      if (d.subiu && DESCE.test(f) && !SOBE.test(f)) { motivo = 'sentido trocado em: ' + f.slice(0, 80); break; }
      if (!d.subiu && SOBE.test(f) && !DESCE.test(f)) { motivo = 'sentido trocado em: ' + f.slice(0, 80); break; }
    }
  }
}
let origem = 'modelo';
if (P.semModelo || motivo) {
  origem = P.semModelo ? 'regras' : 'regras (o texto do modelo foi descartado: ' + motivo + ')';
  if (!P.rel.length && P.comBase >= 3) texto = 'Nada saiu do esperado em relação à sua média dos últimos 30 dias.';
