      let tot = h2m(p.totalSleep); if (tot === null) tot = h2m(p.asleep);
      const deep = h2m(p.deep), rem = h2m(p.rem), core = h2m(p.core), cama = h2m(p.inBed);
      if (tot === null && (deep !== null || rem !== null || core !== null)) tot = (deep || 0) + (rem || 0) + (core || 0);
      if ((tot === null || tot <= 0) && cama !== null && cama > 0) { const o = porDia[dd] = porDia[dd] || {}; o.sono_cama = { s: cama, n: 1, modo: 'ultimo' }; }
      if (tot !== null && tot > 0) { const o = porDia[dd] = porDia[dd] || {}; o.sono_total = { s: tot, n: 1, modo: 'ultimo' }; if (deep !== null) o.sono_profundo = { s: deep, n: 1, modo: 'ultimo' }; if (rem !== null) o.sono_rem = { s: rem, n: 1, modo: 'ultimo' }; }
    }
