      // qualquer outra métrica que chegar: guarda o valor do dia para comparar com o padrão da própria pessoa
      sd.saude.un = sd.saude.un || {};
      if (nome === 'blood_pressure') {
        const sis = num(p.systolic), dia2 = num(p.diastolic);
        if (sis !== null) reg(d, 'x:pressao_sistolica', sis, 'media');
        if (dia2 !== null) reg(d, 'x:pressao_diastolica', dia2, 'media');
        sd.saude.un['x:pressao_sistolica'] = 'mmHg'; sd.saude.un['x:pressao_diastolica'] = 'mmHg';
        continue;
      }
