  for (const k of Object.keys(porDia[d])) {
    const c = porDia[d][k];
    let v = c.modo === 'soma' ? c.s : c.s / c.n;
    sd.saude.dias[d][k] = k.indexOf('x:') === 0 ? Math.round(v * 100) / 100 : Math.round(v * 10) / 10;
    if (k.indexOf('x:') === 0) { sd.saude.modo = sd.saude.modo || {}; sd.saude.modo[k] = c.modo; }
    if (k === 'glicose') sd.saude.dias[d].glicose_min = Math.round(c.min);
  }
}
